import {context,page,expect,extensionId,installEdgeExtensionHooks,test,textRequests,visionRequests,createTwoPageTextPdf,selectElementText,OVERLEAF_FIXTURE_URL,setStoredSidebarMode} from './support/edge-extension-fixture';
import {clickPdfReaderAction,openTranslationMore} from './support/translation-controls';
