installEdgeExtensionHooks();
const worker=()=>context.serviceWorkers()[0]!;
const snapshot=()=>worker().evaluate(async()=>await(globalThis as any).chrome.storage.local.get(null));
function expectStableReadingSnapshot(after:Record<string,unknown>,before:Record<string,unknown>){
 const withoutTime=(value:unknown)=>JSON.stringify(value,(key,item)=>key==='updatedAt'?undefined:item);
 expect(Object.keys(after).sort()).toEqual(Object.keys(before).sort());
 for(const key of Object.keys(before))if(key==='piPdfReadingStatesV1'||key==='piRecentPdfDocumentsV1')expect(withoutTime(after[key])).toBe(withoutTime(before[key]));else expect(after[key]).toEqual(before[key]);
}
async function preserve(run:()=>Promise<void>){const old=await worker().evaluate(async()=>{const s=(globalThis as any).chrome.storage;return {local:await s.local.get(null),session:await s.session.get(null)}});try{await run()}finally{await worker().evaluate(async old=>{const s=(globalThis as any).chrome.storage;await s.local.clear();await s.session.clear();await s.local.set(old.local);await s.session.set(old.session)},old)}}
const sources=['The power depends on sample size and confidence interval.','The kernel maps a sample.'];
const profiles=[{id:'statistics',name:'统计学',entries:[{source:'power',target:'统计功效'},{source:'sample size',target:'样本量'},{source:'confidence interval',target:'置信区间'}]},{id:'energy',name:'能源',entries:[{source:'voltage',target:'电压'},{source:'current',target:'电流'}]}];
function retainedPaper(){
 const buffer=createTwoPageTextPdf(sources[0]!,sources[1]!),signatures=sources.map((text,index)=>pdfDocumentTranslationSessionBlockSignature(index+1,text,0));
 const formula={version:1 as const,sourceTemplate:'{{m1}}',translationTemplate:'核函数映射样本 {{m1}}。',formulas:[{id:'m1',latex:'x=y',display:false}],issues:[]};
 const record={documentKey:pdfDocumentTranslationSessionDocumentKey('assistance-paper'),targetLanguage:'zh-CN',sourceLanguage:'auto',style:'academic',contentMode:'auto',activity:'complete',updatedAt:Date.now(),behaviorKey:pdfDocumentTranslationSessionBehaviorKey('old'),sourceFingerprint:createHash('sha256').update(buffer).digest('hex'),documentSignatures:signatures,scopeSignatures:signatures,preservedSignatures:[],blocks:[{signature:signatures[0],pageNumber:1,translatedText:'功效取决于样本量和置信区间。'},{signature:signatures[1],pageNumber:2,translatedText:formula.translationTemplate,formulaDocument:formula,manualCorrection:true,revisions:[{id:'revision-assistance',createdAt:1,reason:'correction',translatedText:'内核映射样本 {{m1}}。',formulaDocument:{...formula,translationTemplate:'内核映射样本 {{m1}}。'}}]}]};
 return {buffer,record};
}
async function seed(p:ReturnType<typeof retainedPaper>,language='zh-CN'){
 await worker().evaluate(async({record,language,profiles})=>{const s=(globalThis as any).chrome.storage.local,settings=(await s.get('extensionSettings')).extensionSettings;await s.set({uiLanguagePreference:language,extensionSettings:{...settings,academicGlossary:[{source:'kernel',target:'内核'}],glossaryProfiles:profiles,activeGlossaryProfileId:'general',documentGlossaryProfiles:{}},pdfDocumentTranslationRetainedV1:[record],documentTranslationMemoryV1:{}})},{record:p.record,language,profiles});
}
async function openPaper(reader:Page,p:ReturnType<typeof retainedPaper>){
 const id=JSON.stringify(['pdf',p.record.documentKey,'zh-CN','auto','academic','auto']);await reader.goto(`chrome-extension://${extensionId}/pdf.html?restore=${encodeURIComponent(id)}`);await reader.locator('#file-input').setInputFiles({name:'assistance-paper.pdf',mimeType:'application/pdf',buffer:p.buffer});await expect(reader.locator('#pdf-document-translation')).toHaveAttribute('data-phase','complete');
 await reader.locator('#pdf-document-translation-copy-menu > summary').click();await reader.locator('#pdf-document-terms').click();await expect(reader.locator('.document-glossary select')).toBeEnabled();
 await expect.poll(async()=>((await snapshot()).pdfDocumentTranslationRetainedV1 as any[])[0]?.plan?.mode).toBe('all');
 const restored=((await snapshot()).pdfDocumentTranslationRetainedV1 as any[])[0];
 expect(Object.fromEntries(restored.blocks.map((block:any)=>[block.signature,block]))).toEqual(Object.fromEntries(p.record.blocks.map(block=>[block.signature,block])));
 expect(await reader.evaluate(()=>document.documentElement.scrollWidth-innerWidth)).toBeLessThanOrEqual(1);
 expect(await reader.locator('#pdf-terms-dialog').evaluate(node=>node.scrollWidth-node.clientWidth)).toBeLessThanOrEqual(1);
}
function bibliographicPdf(){
 const original=createTwoPageTextPdf('Original research selection. doi: 10.1234/local-paper','More original observations.').toString('binary');
 const objects=[...original.matchAll(/\d+ 0 obj\n([\s\S]*?)\nendobj/gu)].map(match=>match[1]!);
 const info=objects.length+1,metadata=objects.length+2;
 objects[0]=objects[0]!.replace(/>>$/u,`/Metadata ${metadata} 0 R >>`);
 objects.push('<< /Title (Local research title) /Author (Jane Doe) /CreationDate (D:20260101) >>');
 const xml='<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:prism="http://prismstandard.org/namespaces/basic/2.0/"><prism:publicationDate>2024-03-01</prism:publicationDate></rdf:Description></rdf:RDF></x:xmpmeta>';
 objects.push(`<< /Type /Metadata /Subtype /XML /Length ${Buffer.byteLength(xml)} >>\nstream\n${xml}\nendstream`);
 let body='%PDF-1.4\n';const offsets=[0];objects.forEach((object,index)=>{offsets.push(Buffer.byteLength(body,'binary'));body+=`${index+1} 0 obj\n${object}\nendobj\n`});const xref=Buffer.byteLength(body,'binary');
 body+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(offset=>`${String(offset).padStart(10,'0')} 00000 n \n`).join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R /Info ${info} 0 R >>\nstartxref\n${xref}\n%%EOF`;
 return Buffer.from(body,'binary');
}
async function areaNote(reader:Page,note:string){
 await clickPdfReaderAction(reader,'region-translate');const rect=(await reader.locator('.pdf-page').first().boundingBox())!;await reader.mouse.move(rect.x+30,rect.y+80);await reader.mouse.down();await reader.mouse.move(rect.x+220,rect.y+180,{steps:8});await reader.mouse.up();await reader.locator('.region-confirm').getByRole('button',{name:'区域笔记',exact:true}).click();const dialog=reader.getByRole('dialog',{name:'区域笔记',exact:true});await dialog.getByRole('textbox').fill(note);await dialog.getByRole('button',{name:'保存笔记',exact:true}).click();await expect(dialog).toHaveCount(0);
}
